export type Ticket = { title: string; priority: "low" | "normal" | "high"; hours: number };
export type Completion = { text: string; inputTokens: number; outputTokens: number };
export type Complete = { (prompt: string, maxTokens: number): Promise<Completion> };
export type Log = { (event: string, fields: Record<string, string | number>): void };

const instruction =
    "Return only JSON with a title string, a priority of low, normal, or high, and hours as a number from 1 to 40.";

export function parseTicket(raw: string): Ticket | null {
    let value: unknown;
    try {
        value = JSON.parse(raw);
    } catch {
        return null;
    }
    if (typeof value !== "object" || value === null) {
        return null;
    }
    const record = value as Record<string, unknown>;
    if (typeof record.title !== "string" || record.title.trim().length === 0) {
        return null;
    }
    if (record.priority !== "low" && record.priority !== "normal" && record.priority !== "high") {
        return null;
    }
    if (typeof record.hours !== "number" || !Number.isFinite(record.hours) || record.hours < 1 || record.hours > 40) {
        return null;
    }
    return { title: record.title.trim(), priority: record.priority, hours: record.hours };
}

export async function extractTicket(
    note: string,
    complete: Complete,
    log: Log,
    budgetTokens: number,
): Promise<Ticket | null> {
    let prompt = instruction + "\n\nNote:\n" + note;
    let spent = 0;
    for (let attempt = 1; attempt <= 3; attempt += 1) {
        if (spent >= budgetTokens) {
            log("ticket.budget", { attempt: attempt, spent: spent });
            return null;
        }
        const result = await complete(prompt, 400);
        spent += result.inputTokens + result.outputTokens;
        const ticket = parseTicket(result.text);
        if (ticket !== null) {
            log("ticket.extracted", { attempt: attempt, spent: spent, titleLength: ticket.title.length });
            return ticket;
        }
        prompt = instruction + "\n\nThe previous reply failed validation. Return the JSON object again.\n\nNote:\n" + note;
    }
    log("ticket.rejected", { attempts: 3, spent: spent });
    return null;
}
